import{_ as o,o as t,c as a,a3 as c}from"./chunks/framework.cNy3aYYk.js";const m=JSON.parse('{"title":"Tenant API v1 — Contacts","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Contacts | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-contacts"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Contacts | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-contacts"}]]},"headers":[],"relativePath":"api/tenant-v1-contacts.md","filePath":"api/tenant-v1-contacts.md","lastUpdated":1791478559000}'),d={name:"api/tenant-v1-contacts.md"};function s(n,e,i,r,l,p){return t(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="tenant-api-v1-—-contacts" tabindex="-1">Tenant API v1 — Contacts <a class="header-anchor" href="#tenant-api-v1-—-contacts" aria-label="Permalink to &quot;Tenant API v1 — Contacts&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>verified</code>, <code>module:contacts</code>, plus permission middleware / policies.</p><p>Assignee scoping: without <code>contacts.assign</code> (and not superadmin), list/stats/view/update only include contacts where <code>assigned_to</code> is the current user.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-contacts-stats" tabindex="-1">GET <code>/contacts/stats</code> <a class="header-anchor" href="#get-contacts-stats" aria-label="Permalink to &quot;GET `/contacts/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Payload includes:</p><p><code>total_contacts</code>, <code>my_contacts</code>, <code>unassigned</code>, <code>with_email</code>, <code>created_this_week</code>, <code>on_boarded</code>, <code>off_boarded</code>, <code>todays_follow_ups</code>, <code>overdue_follow_ups</code>, <code>scope</code> (<code>org</code>|<code>mine</code>).</p><h2 id="contacts-crud" tabindex="-1">Contacts CRUD <a class="header-anchor" href="#contacts-crud" aria-label="Permalink to &quot;Contacts CRUD&quot;">​</a></h2><h3 id="get-contacts" tabindex="-1">GET <code>/contacts</code> <a class="header-anchor" href="#get-contacts" aria-label="Permalink to &quot;GET `/contacts`&quot;">​</a></h3><p>Query: <code>search</code>, <code>company</code>, <code>company_id</code>, <code>lifecycle_status</code> (<code>on_boarded</code> | <code>off_boarded</code>), <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_contacts</code>, <code>trashed</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>lifecycle_status</code>, <code>latest_note</code> — most recent note (<code>id</code>, <code>body</code>, <code>author</code>, timestamps) or <code>null</code>, <code>next_follow_up_at</code> (denormalized due timestamp for the earliest <strong>pending</strong> follow-up), and <code>next_follow_up</code> (the full follow-up object, or <code>null</code>). May include <code>company_id</code> and <code>linked_company</code> when the relationship is loaded.</p><h3 id="post-contacts" tabindex="-1">POST <code>/contacts</code> <a class="header-anchor" href="#post-contacts" aria-label="Permalink to &quot;POST `/contacts`&quot;">​</a></h3><p>Body: <code>name</code> (required), <code>email</code>, <code>phone</code>, <code>company</code> (legacy free-text), <code>company_id</code> (optional FK to Companies), <code>job_title</code>, <code>source</code>, <code>lifecycle_status</code> (default <code>on_boarded</code>), <code>assigned_to</code>.</p><p>When <code>company_id</code> is set and the company exists, the legacy <code>company</code> string is synced to that Company’s name.</p><h3 id="get-contacts-id" tabindex="-1">GET <code>/contacts/{id}</code> <a class="header-anchor" href="#get-contacts-id" aria-label="Permalink to &quot;GET `/contacts/{id}`&quot;">​</a></h3><p>Includes assignee, creator, notes, activities, follow-ups. May include <code>company_id</code> and <code>linked_company</code> (<code>id</code>, <code>uuid</code>, <code>name</code>) when the relationship is loaded. Embedded <code>notes</code> and <code>activities</code> are <strong>newest-first</strong> (<code>created_at</code> DESC, then <code>id</code> DESC). Embedded <code>follow_ups</code> keep product scheduling order (not reversed as a chat feed).</p><h3 id="put-contacts-id" tabindex="-1">PUT <code>/contacts/{id}</code> <a class="header-anchor" href="#put-contacts-id" aria-label="Permalink to &quot;PUT `/contacts/{id}`&quot;">​</a></h3><p>Partial update of contact fields (including <code>assigned_to</code>, <code>company</code>, <code>company_id</code>).</p><h3 id="delete-contacts-id" tabindex="-1">DELETE <code>/contacts/{id}</code> <a class="header-anchor" href="#delete-contacts-id" aria-label="Permalink to &quot;DELETE `/contacts/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>contacts.delete</code>.</p><h3 id="post-contacts-id-restore" tabindex="-1">POST <code>/contacts/{id}/restore</code> <a class="header-anchor" href="#post-contacts-id-restore" aria-label="Permalink to &quot;POST `/contacts/{id}/restore`&quot;">​</a></h3><p>Restore a soft-deleted contact. Permission: <code>contacts.restore</code>.</p><h3 id="delete-contacts-id-force" tabindex="-1">DELETE <code>/contacts/{id}/force</code> <a class="header-anchor" href="#delete-contacts-id-force" aria-label="Permalink to &quot;DELETE `/contacts/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted contact (must already be trashed). Permission: <code>contacts.force.delete</code> (owner by default).</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-contacts-id-assign" tabindex="-1">POST <code>/contacts/{id}/assign</code> <a class="header-anchor" href="#post-contacts-id-assign" aria-label="Permalink to &quot;POST `/contacts/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><h3 id="post-contacts-id-notes" tabindex="-1">POST <code>/contacts/{id}/notes</code> <a class="header-anchor" href="#post-contacts-id-notes" aria-label="Permalink to &quot;POST `/contacts/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><h3 id="get-contacts-id-timeline" tabindex="-1">GET <code>/contacts/{id}/timeline</code> <a class="header-anchor" href="#get-contacts-id-timeline" aria-label="Permalink to &quot;GET `/contacts/{id}/timeline`&quot;">​</a></h3><p>Contact activity timeline entries.</p><h2 id="follow-ups-1-7-0" tabindex="-1">Follow-ups (1.7.0) <a class="header-anchor" href="#follow-ups-1-7-0" aria-label="Permalink to &quot;Follow-ups (1.7.0)&quot;">​</a></h2><p>Permission: <code>contacts.update</code> for all follow-up routes.</p><h3 id="post-contacts-id-follow-ups" tabindex="-1">POST <code>/contacts/{id}/follow-ups</code> <a class="header-anchor" href="#post-contacts-id-follow-ups" aria-label="Permalink to &quot;POST `/contacts/{id}/follow-ups`&quot;">​</a></h3><p><code>{ &quot;title&quot;, &quot;due_at&quot;, &quot;notes&quot;?, &quot;assigned_to&quot;? }</code>. <code>assigned_to</code> defaults to the contact&#39;s assignee when omitted. Creating a follow-up sets <code>contacts.next_follow_up_at</code> to the earliest <strong>pending</strong> follow-up&#39;s <code>due_at</code> and (when Calendar is entitled) upserts a <code>contact</code> calendar projection.</p><h3 id="put-contacts-id-follow-ups-followupid" tabindex="-1">PUT <code>/contacts/{id}/follow-ups/{followUpId}</code> <a class="header-anchor" href="#put-contacts-id-follow-ups-followupid" aria-label="Permalink to &quot;PUT `/contacts/{id}/follow-ups/{followUpId}`&quot;">​</a></h3><p>Partial update (<code>title</code>, <code>due_at</code>, <code>notes</code>, <code>assigned_to</code>). Changing <code>due_at</code> recomputes <code>next_follow_up_at</code> and is treated as a reschedule in the activity timeline.</p><h3 id="post-contacts-id-follow-ups-followupid-complete" tabindex="-1">POST <code>/contacts/{id}/follow-ups/{followUpId}/complete</code> <a class="header-anchor" href="#post-contacts-id-follow-ups-followupid-complete" aria-label="Permalink to &quot;POST `/contacts/{id}/follow-ups/{followUpId}/complete`&quot;">​</a></h3><p>Marks the follow-up <strong>completed</strong>, recomputes <code>next_follow_up_at</code> from remaining pending follow-ups, and clears the calendar projection when none remain.</p><p>Due/overdue reminders (workspace-local &quot;today&quot;) are sent by the daily <code>crm:send-due-notifications</code> job — one notification per follow-up per day, to the follow-up&#39;s <code>assigned_to</code> (falling back to the contact&#39;s assignee).</p><h2 id="import-export-1-7-0" tabindex="-1">Import / Export (1.7.0) <a class="header-anchor" href="#import-export-1-7-0" aria-label="Permalink to &quot;Import / Export (1.7.0)&quot;">​</a></h2><p>Permission for export: <code>contacts.export</code>. Permission for all import routes: <code>contacts.import</code> (+ <code>module:contacts</code>). Duplicate mode <code>update</code> also requires <code>contacts.update</code>.</p><h3 id="get-contacts-export" tabindex="-1">GET <code>/contacts/export</code> <a class="header-anchor" href="#get-contacts-export" aria-label="Permalink to &quot;GET `/contacts/export`&quot;">​</a></h3><p>Query: same filters as list, plus <code>format</code> = <code>csv</code> (default) or <code>xlsx</code>. Streams a download of the filtered set (id, name, email, phone, company, job title, source, lifecycle status, assignee, creator, next follow-up, created at).</p><h3 id="get-contacts-import-template" tabindex="-1">GET <code>/contacts/import/template</code> <a class="header-anchor" href="#get-contacts-import-template" aria-label="Permalink to &quot;GET `/contacts/import/template`&quot;">​</a></h3><p>Query: <code>format</code> = <code>csv</code> (default) or <code>xlsx</code>. Downloads a sample template with all mappable columns and one sample row.</p><h3 id="get-contacts-imports" tabindex="-1">GET <code>/contacts/imports</code> <a class="header-anchor" href="#get-contacts-imports" aria-label="Permalink to &quot;GET `/contacts/imports`&quot;">​</a></h3><p>Paginated import history (status, user, file name, row counts, timestamps).</p><h3 id="post-contacts-imports" tabindex="-1">POST <code>/contacts/imports</code> <a class="header-anchor" href="#post-contacts-imports" aria-label="Permalink to &quot;POST `/contacts/imports`&quot;">​</a></h3><p>Multipart: <code>file</code> (CSV/XLSX). Stores the upload, returns import record + <code>context</code> (headers, sample rows, suggested mapping, fields). Status: <code>uploaded</code>.</p><h3 id="put-contacts-imports-uuid" tabindex="-1">PUT <code>/contacts/imports/{uuid}</code> <a class="header-anchor" href="#put-contacts-imports-uuid" aria-label="Permalink to &quot;PUT `/contacts/imports/{uuid}`&quot;">​</a></h3><p>Body: <code>{ &quot;mapping&quot;: { &quot;name&quot;: &quot;Name&quot;, &quot;email&quot;: &quot;Email&quot;, ... } }</code>. Status → <code>mapped</code>. Mappable fields: <code>name</code> (required), <code>email</code>, <code>phone</code>, <code>company</code>, <code>job_title</code>, <code>source</code>, <code>lifecycle_status</code>, <code>assigned_to</code>.</p><h3 id="put-contacts-imports-uuid-options" tabindex="-1">PUT <code>/contacts/imports/{uuid}/options</code> <a class="header-anchor" href="#put-contacts-imports-uuid-options" aria-label="Permalink to &quot;PUT `/contacts/imports/{uuid}/options`&quot;">​</a></h3><p>Body: <code>{ &quot;unique_fields&quot;: [&quot;email&quot;,&quot;phone&quot;], &quot;duplicate_mode&quot;: &quot;skip&quot;|&quot;update&quot;|&quot;keep&quot; }</code>. <code>duplicate_mode=update</code> requires <code>contacts.update</code>.</p><p>Unlike Leads, Contact import has <strong>no <code>assignment_mode</code></strong> — there is no equal-distribute option. An <code>assigned_to</code> column value (resolved by user email) sets the assignee directly; rows without one are unassigned unless the importer&#39;s business rules apply (<code>ContactService::create</code> mirrors manual create).</p><h3 id="post-contacts-imports-uuid-preview" tabindex="-1">POST <code>/contacts/imports/{uuid}/preview</code> <a class="header-anchor" href="#post-contacts-imports-uuid-preview" aria-label="Permalink to &quot;POST `/contacts/imports/{uuid}/preview`&quot;">​</a></h3><p>Validates rows without writing contacts. Returns preview counts + sample validation errors.</p><h3 id="post-contacts-imports-uuid-run" tabindex="-1">POST <code>/contacts/imports/{uuid}/run</code> <a class="header-anchor" href="#post-contacts-imports-uuid-run" aria-label="Permalink to &quot;POST `/contacts/imports/{uuid}/run`&quot;">​</a></h3><p>Queues <code>ProcessContactImportJob</code> on the <code>imports</code> queue. Status → <code>queued</code> → <code>processing</code> → <code>completed</code>|<code>failed</code>. Poll <code>GET /contacts/imports/{uuid}</code>.</p><h3 id="get-contacts-imports-uuid" tabindex="-1">GET <code>/contacts/imports/{uuid}</code> <a class="header-anchor" href="#get-contacts-imports-uuid" aria-label="Permalink to &quot;GET `/contacts/imports/{uuid}`&quot;">​</a></h3><p>Status + statistics for polling (<code>processed_rows</code> / <code>total_rows</code>, imported/updated/skipped/duplicate/failed counts).</p><h3 id="get-contacts-imports-uuid-file" tabindex="-1">GET <code>/contacts/imports/{uuid}/file</code> <a class="header-anchor" href="#get-contacts-imports-uuid-file" aria-label="Permalink to &quot;GET `/contacts/imports/{uuid}/file`&quot;">​</a></h3><p>Download the original uploaded file.</p><h3 id="get-contacts-imports-uuid-failed-records" tabindex="-1">GET <code>/contacts/imports/{uuid}/failed-records</code> <a class="header-anchor" href="#get-contacts-imports-uuid-failed-records" aria-label="Permalink to &quot;GET `/contacts/imports/{uuid}/failed-records`&quot;">​</a></h3><p>Download <code>failed_records.csv</code> (original row + reason + validation errors).</p><h3 id="get-contacts-imports-uuid-error-report" tabindex="-1">GET <code>/contacts/imports/{uuid}/error-report</code> <a class="header-anchor" href="#get-contacts-imports-uuid-error-report" aria-label="Permalink to &quot;GET `/contacts/imports/{uuid}/error-report`&quot;">​</a></h3><p>Download <code>error_report.csv</code> (technical/processing exceptions).</p><h2 id="billing-summary-statement" tabindex="-1">Billing summary &amp; statement <a class="header-anchor" href="#billing-summary-statement" aria-label="Permalink to &quot;Billing summary &amp; statement&quot;">​</a></h2><p>Requires Contacts <strong>view</strong>. Invoice/payment/credit-note lines appear only when those modules are entitled.</p><h3 id="get-contacts-id-billing-summary" tabindex="-1">GET <code>/contacts/{id}/billing-summary</code> <a class="header-anchor" href="#get-contacts-id-billing-summary" aria-label="Permalink to &quot;GET `/contacts/{id}/billing-summary`&quot;">​</a></h3><p>Returns <code>{ currencies: [{ currency, invoice_count, total_invoiced, total_paid, balance_due }] }</code> for non-draft, non-cancelled invoices. Empty <code>currencies</code> when Invoices is not entitled or there is no data.</p><h3 id="get-contacts-id-statement" tabindex="-1">GET <code>/contacts/{id}/statement</code> <a class="header-anchor" href="#get-contacts-id-statement" aria-label="Permalink to &quot;GET `/contacts/{id}/statement`&quot;">​</a></h3><p>Query: <code>from</code>, <code>to</code> (optional <code>YYYY-MM-DD</code>; defaults cover a sensible workspace range). Chronological lines (<code>invoice</code> | <code>payment</code> | <code>credit_note</code>) with <code>date</code>, <code>number</code>, <code>description</code>, <code>amount</code>, <code>currency</code>, plus period <code>totals</code>, <code>opening_balance</code> (outstanding before <code>from</code>), and <code>balance_due</code> (closing as of <code>to</code>) per currency. Credit notes appear only when <strong>applied</strong> (draft/issued/refunded/void excluded), matching aged receivables treatment.</p><h3 id="get-contacts-id-statement-pdf" tabindex="-1">GET <code>/contacts/{id}/statement.pdf</code> <a class="header-anchor" href="#get-contacts-id-statement-pdf" aria-label="Permalink to &quot;GET `/contacts/{id}/statement.pdf`&quot;">​</a></h3><p>Same query as statement; returns a branded PDF download.</p><h2 id="lead-conversion" tabindex="-1">Lead conversion <a class="header-anchor" href="#lead-conversion" aria-label="Permalink to &quot;Lead conversion&quot;">​</a></h2><p><code>POST /leads/{lead}/convert</code> (see <a href="/api/tenant-v1-leads">tenant-v1-leads.md</a>) creates a Contact and sets <code>contact_id</code> / <code>contact</code> on the returned lead when the <code>contacts</code> module is entitled for the workspace. <code>conversion_meta.stub</code> is <code>false</code> in that case; it is <code>true</code> when Contacts is not installed (status-only conversion).</p>',78)])])}const h=o(d,[["render",s]]);export{m as __pageData,h as default};
